<?php

namespace App\Application\Newsletter;

/**
 * The outcome of a Dompdf render: generated bytes plus the validation result.
 * The page_target is the exact page count the document must match; `valid`
 * reports whether the regeneration loop converged on it.
 */
final readonly class NewsletterPdfResult
{
    public function __construct(
        public string $bytes,
        public int $pageCount,
        public int $pageTarget,
        public bool $valid,
        public int $attempts,
        public string $layout,
        public string $message,
    ) {}
}
